package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/** The sheet's late percent (two decimals, 0.00 until set). An overdue claim (OPEN, its due-by — its
 *  date plus the terms — before the sheet's today) gains the late percent of its figure for every full
 *  30 days it is overdue, rounded to two decimals by the claim's rounding (see {@link PolicyDate}), on top. The charge is never bound by a
 *  statement; settling freezes it into the settled due. A correction (a negative amount) has no late charge. */
@Service
public class LatePct {

    public static final String KEY = "late-pct";

    public static final String DEFAULT = "0.00";

    private final SettingRepository settings;
    private final SheetClock clock;

    public LatePct(SettingRepository settings, SheetClock clock) {
        this.settings = settings;
        this.clock = clock;
    }

    /** The late charge as it stands on the sheet's today. */
    public Charge of(String sheetId) {
        return new Charge(new BigDecimal(settings.find(sheetId, KEY).orElse(DEFAULT)),
                Integer.parseInt(settings.find(sheetId, Terms.KEY).orElse(Terms.DEFAULT)), clock.today(sheetId));
    }

    /** The late percent, the terms and the day the charge is worked out on. */
    public record Charge(BigDecimal pct, int terms, LocalDate today) {

        /** The figure with the claim's late charge, rounded by {@code mode}, on top; null (n/a) stays null. */
        public BigDecimal addTo(Claim claim, BigDecimal figure, RoundingMode mode) {
            if (figure == null || claim.getStatus() != ClaimStatus.OPEN || claim.isCorrection()) return figure;
            long late = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today);
            if (late <= 0) return figure;
            long periods = late / 30;
            return figure.add(figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
                    .divide(BigDecimal.valueOf(100), 2, mode));
        }
    }
}
package net.officefloor.hq.app.setting;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/** The sheet's policy date (yyyy-MM-dd; blank until set, when it is the sheet's today). A claim dated
 *  before it rounds its live figures (the rate step and the late charge) half up, one dated on or after it
 *  half to even. A correction rounds by the date of the claim it corrects. Settled and bound figures keep
 *  the figure they were fixed at. */
@Service
public class PolicyDate {

    public static final String KEY = "policy-date";

    private final SettingRepository settings;
    private final SheetClock clock;
    private final ClaimRepository claims;

    public PolicyDate(SettingRepository settings, SheetClock clock, ClaimRepository claims) {
        this.settings = settings;
        this.clock = clock;
        this.claims = claims;
    }

    /** The rounding policy as it stands on the sheet now. */
    public Policy of(String sheetId) {
        LocalDate date = settings.find(sheetId, KEY).map(LocalDate::parse).orElseGet(() -> clock.today(sheetId));
        return new Policy(date, claims.findBySheet(sheetId));
    }

    /** The policy date and the sheet's claims, which a correction's corrected claim is found among. */
    public record Policy(LocalDate date, List<Claim> claims) {

        /** How the claim's live figures round. */
        public RoundingMode modeFor(Claim claim) {
            return roundsOn(claim).isBefore(date) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
        }

        /** The claim's date, or for a correction the date of the claim it corrects. */
        private LocalDate roundsOn(Claim claim) {
            if (!claim.isCorrection()) return claim.getDate();
            return claims.stream()
                    .filter(c -> c.getPersonId() == claim.getPersonId() && claim.getCorrects().equals(c.getNumber()))
                    .map(Claim::getDate).findFirst().orElse(claim.getDate());
        }
    }
}
