105	/** The sheet's late percent (two decimals, 0.00 until set). An overdue claim (OPEN, its due-by — its
106	 *  date plus the terms — before the sheet's today) gains the late percent of its figure for every full
107	 *  30 days it is overdue, rounded to two decimals by the claim's rounding (see {@link PolicyDate}), on top. The charge is never bound by a
108	 *  statement; settling freezes it into the settled due. A correction (a negative amount) has no late charge. */
109	@Service
110	public class LatePct {
111	
112	    public static final String KEY = "late-pct";
113	
114	    public static final String DEFAULT = "0.00";
115	
116	    private final SettingRepository settings;
117	    private final SheetClock clock;
118	
119	    public LatePct(SettingRepository settings, SheetClock clock) {
120	        this.settings = settings;
121	        this.clock = clock;
122	    }
123	
124	    /** The late charge as it stands on the sheet's today. */
125	    public Charge of(String sheetId) {
126	        return new Charge(new BigDecimal(settings.find(sheetId, KEY).orElse(DEFAULT)),
127	                Integer.parseInt(settings.find(sheetId, Terms.KEY).orElse(Terms.DEFAULT)), clock.today(sheetId));
128	    }
129	
130	    /** The late percent, the terms and the day the charge is worked out on. */
131	    public record Charge(BigDecimal pct, int terms, LocalDate today) {
132	
133	        /** The figure with the claim's late charge, rounded by {@code mode}, on top; null (n/a) stays null. */
134	        public BigDecimal addTo(Claim claim, BigDecimal figure, RoundingMode mode) {
135	            if (figure == null || claim.getStatus() != ClaimStatus.OPEN || claim.isCorrection()) return figure;
136	            long late = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today);
137	            if (late <= 0) return figure;
138	            long periods = late / 30;
139	            return figure.add(figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
140	                    .divide(BigDecimal.valueOf(100), 2, mode));
141	        }
142	    }
143	}
