438	/** The claims of each sheet, newest first. */
439	@Repository
440	public class ClaimRepository {
441	
442	    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getString("sheet_id"),
443	            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(),
444	            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
445	            rs.getObject("claim_number", Integer.class), rs.getBigDecimal("settled_due"),
446	            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
447	            rs.getObject("corrects", Integer.class));
448	
449	    private final JdbcTemplate jdbc;
450	
451	    public ClaimRepository(JdbcTemplate jdbc) {
452	        this.jdbc = jdbc;
453	    }
454	
455	    public List<Claim> findBySheet(String sheetId) {
456	        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY id DESC", ROW, sheetId);
457	    }
458	
459	    public List<Claim> findByPerson(String sheetId, long personId) {
460	        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC", ROW, sheetId, personId);
461	    }
462	
463	    public Claim findById(String sheetId, long id) {
464	        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
465	        return found.isEmpty() ? null : found.get(0);
466	    }
467	
468	    public Claim create(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, Integer corrects) {
469	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
470	        jdbc.update(con -> {
471	            PreparedStatement ps = con.prepareStatement(
472	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects) VALUES (?, ?, ?, ?, ?, ?)",
473	                    new String[] {"id"});
474	            ps.setString(1, sheetId);
475	            ps.setLong(2, personId);
476	            ps.setBigDecimal(3, amount);
477	            ps.setDate(4, Date.valueOf(date));
478	            ps.setString(5, note);
479	            ps.setObject(6, corrects, Types.INTEGER);
480	            return ps;
481	        }, keys);
482	        return new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null, false, null, corrects);
483	    }
484	
485	    public void save(Claim claim) {
486	        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?,"
487	                + " stated = ?, stated_due = ?, corrects = ? WHERE sheet_id = ? AND id = ?",
488	                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
489	                claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getCorrects(), claim.getSheetId(), claim.getId());
490	    }
491	
492	    /** Gives out the sheet's next claim number. The counter is raised and read in one statement, so
493	     *  claims opened at the same moment never share a number, and the number is never given again. */
494	    public int nextNumber(String sheetId) {
495	        jdbc.update("MERGE INTO sheet (id) KEY (id) VALUES (?)", sheetId);
496	        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE "
497	                + "(UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)", Integer.class, sheetId);
498	    }
499	}
