514	
515	/** Moves the claim to the action's status, refusing a change its current status does not allow.
516	 *  Opening gives the claim the sheet's next number, which it keeps when voided. Settling fixes the claim's
517	 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
518	 *  A claim a statement binds is settled at its bound figure. An overdue claim's late charge is frozen in on top.
519	 *  Both are rounded by the claim's rounding (see {@link PolicyDate}).
520	 *  The user who opened a claim may not settle it (four eyes).
521	 *  Publishes the number the audit line carries. */
522	public class ApplyClaimAction {
523	    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimRepository repository,
524	            PersonRepository people, RateRepository rates, Floor floor, LatePct latePct, PolicyDate policyDate,
525	            Out<ClaimNumber> numberOut,
526	            @RequestParam(value = "user", required = false) String user)
527	            throws InvalidClaimStatusException {
528	        if (!action.allowedFrom(claim.getStatus())) {
529	            throw new InvalidClaimStatusException(
530	                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
531	        }
532	        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
533	            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
534	        }
535	        // The late charge is worked out while the claim is still OPEN, so settling freezes it in.
536	        RoundingMode mode = action != ClaimAction.SETTLE ? null : policyDate.of(claim.getSheetId()).modeFor(claim);
537	        BigDecimal settledDue = action != ClaimAction.SETTLE ? null : latePct.of(claim.getSheetId())
538	                .addTo(claim, claim.isStated() ? claim.getStatedDue() : dueNow(claim, people, rates, floor, mode), mode);
539	        claim.setStatus(action.to());
540	        switch (action) {
541	            case OPEN -> {
542	                claim.setNumber(repository.nextNumber(claim.getSheetId()));
543	                claim.setOpenedBy(user);
544	            }
545	            case SETTLE -> claim.setSettledDue(settledDue);
546	            default -> { }
547	        }
548	        numberOut.set(new ClaimNumber(claim.getNumber()));
549	    }
550	
551	    /** amount × pct / 100, rounded by {@code mode} to two decimals and at least the floor; null when no rate is in force on the claim's date. */
552	    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates, Floor floor, RoundingMode mode) {
553	        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
554	        return Floor.raise(claim, Rate.inForce(rates.findBySheet(claim.getSheetId()), person.gradeOn(claim.getDate()), claim.getDate())
555	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
556	                .orElse(null), floor.of(claim.getSheetId()));
557	    }
558	}
