579	/** Opens each selected claim in list order (people in the order they were added, each person's claims
580	 *  newest first), so their numbers follow that order. Each is opened by the same rules, and writes the same
581	 *  audit lines, as opening it alone; one those rules refuse (or not on the sheet) is left as it is. */
582	public class BulkOpenClaims {
583	    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenRequest request,
584	            @RequestParam(value = "user", required = false) String user, ClaimRepository claims,
585	            PersonRepository people, PeriodRepository periods, RateRepository rates, Floor floor, LatePct latePct,
586	            PolicyDate policyDate, Rollup rollup, Audit audit, Out<BulkOpenResult> resultOut) {
587	        Set<Long> selected = new HashSet<>(request.claimIds());
588	        List<Claim> sheetClaims = claims.findBySheet(sheetId);
589	        List<Claim> ordered = new ArrayList<>();
590	        for (Person person : people.findBySheet(sheetId)) {
591	            for (Claim claim : sheetClaims) {
592	                if (claim.getPersonId() == person.getId() && selected.contains(claim.getId())) ordered.add(claim);
593	            }
594	        }
595	        int opened = 0;
596	        for (Claim claim : ordered) {
597	            Rollup.Snapshot before = rollup.take(sheetId);
598	            ClaimNumber[] number = new ClaimNumber[1];
599	            try {
600	                new CheckClaimActionOpen().check(claim, periods);
601	                new ApplyClaimAction().apply(ClaimAction.OPEN, claim, claims, people, rates, floor, latePct, policyDate,
602	                        n -> number[0] = n, user);
603	            } catch (InvalidClaimStatusException refused) {
604	                continue;
605	            }
606	            claims.save(claim);
607	            new AuditClaimStatus().audit(ClaimAction.OPEN, claim, number[0], user, people, audit);
608	            rollup.changes(sheetId, user, before, rollup.take(sheetId)).forEach(audit::record);
609	            opened++;
610	        }
611	        resultOut.set(new BulkOpenResult(opened, selected.size() - opened));
612	    }
613	}
