                new SettingResponse(LatePct.KEY, repository.find(sheetId, LatePct.KEY).orElse(LatePct.DEFAULT)),
                new SettingResponse(PolicyDate.KEY, repository.find(sheetId, PolicyDate.KEY).orElse(""))));
    }
}

